#!/bin/bash
set -e
mkdir -p /logs/verifier

cat << 'TEST_EOF' > /tmp/test_final_state.py
import os
import pstats
import subprocess

import h5py
import numpy as np
import pytest

SCRIPT = "/home/user/simulate_and_profile.py"
H5_PATH = "/home/user/simulation_results.h5"
VAL_PATH = "/home/user/validation.txt"
PROF_PATH = "/home/user/simulation.prof"
N = 1_000_000


@pytest.fixture(scope="session", autouse=True)
def run_submission():
    assert os.path.exists(SCRIPT), f"Script {SCRIPT} is missing."
    assert os.path.isfile(SCRIPT), f"{SCRIPT} is not a file."

    # Outputs must be regenerated by the submitted script during verification.
    for path in (H5_PATH, VAL_PATH, PROF_PATH):
        if os.path.lexists(path):
            if os.path.isdir(path):
                pytest.fail(f"Expected output path {path} is a directory.")
            os.unlink(path)

    try:
        result = subprocess.run(
            ["python3", SCRIPT],
            cwd="/home/user",
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=240,
        )
    except subprocess.TimeoutExpired:
        pytest.fail("Simulation script did not finish within 240 seconds.")

    assert result.returncode == 0, (
        f"Simulation script exited with status {result.returncode}.\n"
        f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}"
    )


def expected_results():
    t = np.linspace(0.0, 10.0, N)
    rng = np.random.RandomState(42)
    signal = np.exp(-0.5 * t) * np.sin(2.0 * np.pi * 12.5 * t)
    signal = signal + rng.normal(0.0, 0.05, N)
    freq = np.fft.fftfreq(N, d=t[1] - t[0])
    fft_mag = np.abs(np.fft.fft(signal))
    positive = freq > 0
    f_peak = freq[positive][np.argmax(fft_mag[positive])]
    return t, signal, freq, fft_mag, abs(float(f_peak) - 12.5)


def test_script_exists():
    assert os.path.exists(SCRIPT), f"Script {SCRIPT} is missing."
    assert os.path.isfile(SCRIPT), f"{SCRIPT} is not a file."


def test_hdf5_file_exists_and_size():
    assert os.path.exists(H5_PATH), f"HDF5 file {H5_PATH} is missing."
    assert os.path.isfile(H5_PATH), f"{H5_PATH} is not a file."
    size_bytes = os.path.getsize(H5_PATH)
    assert size_bytes > 1_000_000, (
        f"HDF5 file {H5_PATH} is too small ({size_bytes} bytes), datasets might be missing."
    )


def test_hdf5_datasets_and_numerical_contents():
    expected_t, expected_signal, expected_freq, expected_mag, _ = expected_results()

    try:
        with h5py.File(H5_PATH, "r") as h5:
            assert set(h5.keys()) == {"time", "signal", "freq", "fft_mag"}, (
                f"Root datasets are {sorted(h5.keys())}, expected exactly "
                "['fft_mag', 'freq', 'signal', 'time']."
            )
            for name in ("time", "signal", "freq", "fft_mag"):
                assert isinstance(h5[name], h5py.Dataset), f"{name} is not an HDF5 dataset."
                assert h5[name].shape == (N,), f"Dataset {name} has shape {h5[name].shape}, expected {(N,)}."
                assert np.issubdtype(h5[name].dtype, np.number), f"Dataset {name} is not numeric."

            actual_t = h5["time"][:]
            actual_signal = h5["signal"][:]
            actual_freq = h5["freq"][:]
            actual_mag = h5["fft_mag"][:]
    except OSError as exc:
        pytest.fail(f"Could not open {H5_PATH} as HDF5: {exc}")

    assert np.all(np.isfinite(actual_t))
    assert np.all(np.isfinite(actual_signal))
    assert np.all(np.isfinite(actual_freq))
    assert np.all(np.isfinite(actual_mag))
    np.testing.assert_allclose(actual_t, expected_t, rtol=2e-6, atol=2e-7)
    np.testing.assert_allclose(actual_signal, expected_signal, rtol=2e-6, atol=2e-7)
    np.testing.assert_allclose(actual_freq, expected_freq, rtol=2e-6, atol=2e-6)
    np.testing.assert_allclose(actual_mag, expected_mag, rtol=3e-5, atol=1e-3)


def test_validation_file():
    assert os.path.exists(VAL_PATH), f"Validation file {VAL_PATH} is missing."
    assert os.path.isfile(VAL_PATH), f"{VAL_PATH} is not a file."

    with open(VAL_PATH, "r") as f:
        content = f.read().strip()
    try:
        val = float(content)
    except ValueError:
        pytest.fail(f"Content of {VAL_PATH} could not be parsed as a float: {content}")

    assert abs(val) < 1e-4, f"Validation error {val} is greater than expected (should be close to 0.0)."
    _, _, _, _, expected_error = expected_results()
    assert np.isfinite(val)
    assert abs(val - expected_error) < 1e-8, (
        f"Validation error {val} does not match the FFT-derived error {expected_error}."
    )


def test_profiling_file():
    assert os.path.exists(PROF_PATH), f"Profiling file {PROF_PATH} is missing."
    assert os.path.isfile(PROF_PATH), f"{PROF_PATH} is not a file."

    try:
        stats = pstats.Stats(PROF_PATH)
    except Exception as exc:
        pytest.fail(f"Could not parse {PROF_PATH} as a pstats file: {exc}")

    assert stats.total_calls > 0, f"Profiling file {PROF_PATH} contains no function calls."
    profiled_functions = list(stats.stats.keys())
    assert any(os.path.abspath(filename) == SCRIPT and name == "main"
               for filename, _line, name in profiled_functions), (
        "The profile does not contain the submitted script's main function."
    )
    assert any("fft" in name.lower() for _filename, _line, name in profiled_functions), (
        "The profile does not contain an FFT operation."
    )
    assert any(name in {"create_dataset", "__setitem__"} and "h5py" in filename.lower()
               for filename, _line, name in profiled_functions), (
        "The profile does not contain HDF5 dataset writing."
    )
TEST_EOF

if python3 -m pytest --noconftest -c /dev/null -p no:cacheprovider /tmp/test_final_state.py -x --tb=short 2>&1; then
    echo "1" > /logs/verifier/reward.txt
else
    echo "0" > /logs/verifier/reward.txt
fi
